export function createInlineCodemodeSandbox(options = {}) {
    return new InlineCodemodeSandbox({ ...options, wasm: quickjsWasm });
}

execute(request, exchange) {
        return serveCodemodeRemote(request, exchange, {
            wasm: quickjsWasm,
            maxInterruptBudget: this.maxInterruptBudget,
            maxMemoryLimitBytes: this.maxMemoryLimitBytes,
        });
    }

export function renderDeclarations(options) {
    const sections = [];
    const tools = options.tools ?? [];
    if (tools.length > 0) {
        const members = tools.map((tool) => `${docComment(tool.description, INDENT)}${INDENT}${renderToolSignature(tool)}`);
        sections.push(`declare const tools: {\n${members.join("\n")}\n};`);
    }
    const namespaces = new Map();
    for (const global of options.globals ?? []) {
        const dot = global.name.indexOf(".");
        if (dot === -1) {
            sections.push(renderGlobal(`declare function ${global.name}`, global, ""));
            continue;
        }
        const namespace = global.name.slice(0, dot);
        const members = namespaces.get(namespace) ?? [];
        if (members.length === 0)
            namespaces.set(namespace, members);
        members.push(renderGlobal(global.name.slice(dot + 1), global, INDENT));
    }
    for (const [namespace, members] of namespaces) {
        sections.push(`declare const ${namespace}: {\n${members.join("\n")}\n};`);
    }
    return sections.join("\n\n");
}

export function renderToolSignature(tool, options = {}) {
    const input = tool.inputSchema === undefined
        ? "unknown"
        : schemaToType(tool.inputSchema, { maxChars: options.inputMaxChars ?? DEFAULT_INPUT_SCHEMA_MAX_CHARS });
    return `${toCodemodeIdentifier(tool.name)}(args: ${input}): Promise<${renderToolOutputType(tool.outputSchema)}>;`;
}

export function renderToolSample(tool, options = {}) {
    const declaration = `declare const tools: { ${renderToolSignature(tool, options)} };`;
    return `${tool.description?.trim() ?? ""}

codemode tool declaration:
\`\`\`ts
${declaration}
\`\`\``;
}

export function renderToolOutputType(schema) {
    return schema === undefined ? "unknown" : schemaToType(schema);
}

function renderGlobal(head, global, indent) {
    if (global.signature !== undefined) {
        return `${docComment(global.description, indent)}${indent}${head}${global.signature};`;
    }
    const input = global.inputSchema === undefined ? "unknown" : schemaToType(global.inputSchema);
    const output = global.outputSchema === undefined ? "unknown" : schemaToType(global.outputSchema);
    return `${docComment(global.description, indent)}${indent}${head}(args: ${input}): Promise<${output}>;`;
}

function docComment(description, indent) {
    const text = description?.trim();
    if (!text)
        return "";
    const lines = text.replaceAll("*/", "*\\/").split(/\r?\n/);
    if (lines.length === 1)
        return `${indent}/** ${lines[0]} */\n`;
    return `${indent}/**\n${lines.map((line) => `${indent} *${line ? ` ${line}` : ""}`).join("\n")}\n${indent} */\n`;
}

function propertyKey(name) {
    return IDENTIFIER.test(name) ? name : JSON.stringify(name);
}

function union(types) {
    const unique = [...new Set(types)];
    if (unique.includes("unknown"))
        return "unknown";
    return unique.length === 0 ? "never" : unique.join(" | ");
}

export function schemaToType(schema, options = {}) {
    const render = (tags) => toType(schema, { root: schema, resolving: new Set(), expansions: 0, tags });
    const type = render(true);
    if (options.maxChars === undefined || type.length <= options.maxChars)
        return type;
    const untagged = render(false);
    return untagged.length <= options.maxChars ? untagged : "unknown";
}

function resolveRef(ref, root) {
    if (ref !== "#" && !ref.startsWith("#/"))
        return undefined;
    let current = root;
    for (const segment of ref.slice(2).split("/").filter(Boolean)) {
        const key = decodeURIComponent(segment).replaceAll("~1", "/").replaceAll("~0", "~");
        if (typeof current !== "object" || current === null || Array.isArray(current) || !(key in current)) {
            return undefined;
        }
        current = current[key];
    }
    if (typeof current === "boolean")
        return current;
    return typeof current === "object" && current !== null && !Array.isArray(current)
        ? current
        : undefined;
}

function toType(schema, context) {
    if (schema === true)
        return "unknown";
    if (schema === false)
        return "never";
    if (typeof schema !== "object" || schema === null || Array.isArray(schema))
        return "unknown";
    if (typeof schema.$ref === "string") {
        const ref = schema.$ref;
        if (context.resolving.has(ref) || context.expansions >= MAX_REF_EXPANSIONS)
            return "unknown";
        const target = resolveRef(ref, context.root);
        if (target === undefined)
            return "unknown";
        context.expansions++;
        context.resolving.add(ref);
        try {
            return toType(target, context);
        }
        finally {
            context.resolving.delete(ref);
        }
    }
    if ("const" in schema)
        return JSON.stringify(schema.const) ?? "unknown";
    if (Array.isArray(schema.enum))
        return union(schema.enum.map((value) => JSON.stringify(value) ?? "unknown"));
    const variants = Array.isArray(schema.anyOf) ? schema.anyOf : Array.isArray(schema.oneOf) ? schema.oneOf : undefined;
    if (variants)
        return union(variants.map((variant) => toType(variant, context)));
    if (Array.isArray(schema.allOf)) {
        const parts = schema.allOf
            .map((part) => toType(part, context))
            .filter((part) => part !== "unknown");
        return parts.length === 0
            ? "unknown"
            : parts.map((part) => (part.includes(" | ") ? `(${part})` : part)).join(" & ");
    }
    const type = schema.type;
    if (Array.isArray(type))
        return union(type.map((entry) => toType({ ...schema, type: entry }, context)));
    switch (type) {
        case "string":
            return "string";
        case "number":
        case "integer":
            return "number";
        case "boolean":
            return "boolean";
        case "null":
            return "null";
        case "array":
            return arrayType(schema, context);
        case "object":
            return objectType(schema, context);
        case undefined:
            if ("properties" in schema || "additionalProperties" in schema || "required" in schema) {
                return objectType(schema, context);
            }
            if ("items" in schema || "prefixItems" in schema)
                return arrayType(schema, context);
            return "unknown";
        default:
            return "unknown";
    }
}

function arrayType(schema, context) {
    if (schema.items !== undefined && !Array.isArray(schema.items)) {
        return `Array<${toType(schema.items, context)}>`;
    }
    const tuple = Array.isArray(schema.prefixItems)
        ? schema.prefixItems
        : Array.isArray(schema.items)
            ? schema.items
            : [];
    if (tuple.length > 0)
        return `[${tuple.map((item) => toType(item, context)).join(", ")}]`;
    return "unknown[]";
}

function descriptionOf(property) {
    const description = property?.description;
    return typeof description === "string" ? description.trim() : "";
}

function constraintTags(schema) {
    if (typeof schema !== "object" || schema === null || Array.isArray(schema))
        return "";
    const property = schema;
    // Optional fields such as Pydantic's `int | None` keep their constraints in the non-null branch.
    // The branch's constraints apply together with the property's, so both are read.
    const variants = Array.isArray(property.anyOf) ? property.anyOf : property.oneOf;
    const nonNull = Array.isArray(variants)
        ? variants.filter((variant) => variant?.type !== "null")
        : [];
    const branch = nonNull.length === 1 ? nonNull[0] : undefined;
    const branches = typeof branch === "object" && branch !== null && !Array.isArray(branch)
        ? [property, branch]
        : [property];
    // Draft-04 and OpenAPI 3.0 make `minimum`/`maximum` exclusive with a boolean `exclusiveMinimum`/`exclusiveMaximum`.
    const schemas = branches.map((schema) => ({
        ...schema,
        ...(schema.exclusiveMinimum === true ? { minimum: undefined, exclusiveMinimum: schema.minimum } : {}),
        ...(schema.exclusiveMaximum === true ? { maximum: undefined, exclusiveMaximum: schema.maximum } : {}),
    }));
    const tags = [];
    const isInteger = (type) => type === "integer" || (Array.isArray(type) && type.includes("integer"));
    if (schemas.some((schema) => isInteger(schema.type)))
        tags.push("@integer");
    for (const keyword of TAG_KEYWORDS) {
        const values = schemas.map((schema) => schema[keyword]);
        if (LOWER_BOUNDS.has(keyword) || UPPER_BOUNDS.has(keyword)) {
            const numbers = values.filter((value) => typeof value === "number");
            if (numbers.length === 0)
                continue;
            tags.push(`@${keyword} ${LOWER_BOUNDS.has(keyword) ? Math.max(...numbers) : Math.min(...numbers)}`);
            continue;
        }
        for (const value of new Set(values)) {
            if (typeof value === "number" || typeof value === "string")
                tags.push(`@${keyword} ${value}`);
        }
    }
    if (schemas.some((schema) => schema.uniqueItems === true))
        tags.push("@uniqueItems");
    // Annotations, unlike constraints, come from the property itself.
    if (property.default !== undefined && property.default !== null) {
        tags.push(`@default ${JSON.stringify(property.default)}`);
    }
    if (property.deprecated === true)
        tags.push("@deprecated");
    return tags
        .filter((tag) => tag.length <= MAX_TAG_CHARS)
        .map((tag) => tag.replace(LINE_TERMINATORS, (char) => `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`))
        .join(" ");
}

function objectType(schema, context) {
    const properties = typeof schema.properties === "object" && schema.properties !== null && !Array.isArray(schema.properties)
        ? schema.properties
        : {};
    const required = new Set(Array.isArray(schema.required) ? schema.required : []);
    const names = Object.keys(properties).sort();
    const members = names.map((name) => {
        const optional = required.has(name) ? "" : "?";
        return `${propertyKey(name)}${optional}: ${toType(properties[name], context)};`;
    });
    const additional = schema.additionalProperties;
    if (additional !== undefined && additional !== false) {
        const type = additional === true ? "unknown" : toType(additional, context);
        members.push(`[key: string]: ${type};`);
    }
    else if (additional === undefined && names.length === 0) {
        members.push("[key: string]: unknown;");
    }
    if (members.length === 0)
        return "{}";
    const comments = names.map((name) => {
        const lines = descriptionOf(properties[name])
            .split(LINE_TERMINATORS)
            .map((line) => line.trim())
            .filter(Boolean);
        const tags = context.tags ? constraintTags(properties[name]) : "";
        return tags ? [...lines, tags] : lines;
    });
    if (!comments.some((comment) => comment.length > 0))
        return `{ ${members.join(" ")} }`;
    const lines = ["{"];
    comments.forEach((comment, index) => {
        for (const line of comment)
            lines.push(`${INDENT}// ${line}`);
        lines.push(`${INDENT}${members[index].replaceAll("\n", `\n${INDENT}`)}`);
    });
    for (const member of members.slice(names.length))
        lines.push(`${INDENT}${member}`);
    lines.push("}");
    return lines.join("\n");
}

export function toCodemodeIdentifier(name) {
    let identifier = "";
    for (const char of name) {
        const valid = identifier === "" ? /^[A-Za-z_$]$/.test(char) : /^[A-Za-z0-9_$]$/.test(char);
        identifier += valid ? char : "_";
    }
    return identifier === "" ? "_" : identifier;
}

export function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}

function serializeStore(store) {
    const serialized = {};
    for (const [key, value] of Object.entries(store ?? {})) {
        const json = JSON.stringify(value);
        if (json !== undefined)
            serialized[key] = json;
    }
    return serialized;
}

function parseBridgeJson(json, what) {
    try {
        return JSON.parse(json);
    }
    catch {
        throw new BridgeError(`${what} is not valid JSON`);
    }
}

function parseStoreWrites(json) {
    const entries = parseBridgeJson(json, "store writes");
    if (!Array.isArray(entries))
        throw new BridgeError("store writes are not an array");
    const writes = { set: {}, delete: [] };
    for (const entry of entries) {
        if (!Array.isArray(entry) ||
            typeof entry[0] !== "string" ||
            (entry.length === 2 ? typeof entry[1] !== "string" : entry.length !== 1)) {
            throw new BridgeError("store writes contain a malformed entry");
        }
        const [key, value] = entry;
        if (value === undefined)
            writes.delete.push(key);
        else
            writes.set[key] = parseBridgeJson(value, `store value for ${JSON.stringify(key)}`);
    }
    return writes;
}

function parseScriptError(json) {
    const parsed = parseBridgeJson(json, "script error");
    if (typeof parsed !== "object" || parsed === null)
        throw new BridgeError("script error is not an object");
    const { name, message, stack } = parsed;
    if (typeof message !== "string" ||
        (name !== undefined && typeof name !== "string") ||
        (stack !== undefined && typeof stack !== "string")) {
        throw new BridgeError("script error is malformed");
    }
    return { kind: "script", name, message, stack };
}

function checkGlobals(globals) {
    const names = new Set();
    const namespaces = new Set();
    for (const global of globals) {
        const parts = global.name.split(".");
        if (parts.length > 2 || !parts.every((part) => IDENTIFIER.test(part)) || RESERVED_GLOBALS.has(parts[0])) {
            throw new Error(`Invalid global name "${global.name}"`);
        }
        if (names.has(global.name))
            throw new Error(`Global "${global.name}" is already registered`);
        if (parts.length === 2)
            namespaces.add(parts[0]);
        names.add(global.name);
    }
    for (const name of namespaces) {
        if (names.has(name))
            throw new Error(`Global "${name}" conflicts with the namespace "${name}"`);
    }
}

deliver(seq, now, id, outcome) {
        if (this.finished)
            return;
        if (!Number.isFinite(now))
            throw new Error(`The clock value of result ${seq} is not a finite number`);
