function workerLauncher(options) {
    return async (data, events) => {
        let module;
        try {
            module = await (options.wasm ?? loadQuickJSWasm());
        }
        catch (error) {
            throw new Error(`Failed to load QuickJS: ${errorMessage(error)}`);
        }
        const interrupt = new SharedArrayBuffer(4);
        const workerData = { ...data, wasm: module, interrupt };
        const releaseWorker = options.acquireWorker?.();
        let worker;
        try {
            worker = new Worker(options.workerUrl ?? defaultWorkerUrl(), { workerData });
        }
        catch (error) {
            releaseWorker?.();
            throw new Error(`Failed to start worker: ${errorMessage(error)}`);
        }
        if (releaseWorker)
            worker.once("exit", releaseWorker);
        worker.on("message", (message) => {
            // Node 24/26 --watch leaks dependency reports onto the worker channel (nodejs/node#65044).
            if (typeof message === "object" &&
                message !== null &&
                ("watch:import" in message || "watch:require" in message))
                return;
            events.message(message);
        });
        worker.on("error", (error) => {
            events.failure({
                kind: "sandbox",
                name: error instanceof Error ? error.name : undefined,
                message: errorMessage(error),
            });
        });
        worker.on("exit", (code) => {
            events.failure({ kind: "sandbox", message: `Worker exited with code ${code} before the script settled` });
        });
        const stop = async () => {
            Atomics.store(new Int32Array(interrupt), 0, 1);
            // A non-interruptible built-in can delay Bun's terminate() until it returns (#10748).
            // Do not hold up the result while that worker exits.
            void worker.terminate().catch(() => undefined);
            // terminate() refs the worker internally; unref it after requesting termination.
            worker.unref();
        };
        try {
            options.onWorkerStarted?.(new Promise((resolve) => worker.once("exit", () => resolve())));
        }
        catch (error) {
            void stop();
            throw error;
        }
        return { post: (message) => worker.postMessage(message), stop };
    };
}

export function inlineLauncher(wasm, interruptBudget = DEFAULT_INTERRUPT_BUDGET) {
    return async (data, events) => {
        let module;
        try {
            module = await wasm;
        }
        catch (error) {
            throw new Error(`Failed to load QuickJS: ${errorMessage(error)}`);
        }
        let stopped = false;
        let settled = false;
        let polls = 0;
        let exhausted = false;
        const session = await startVm({
            data,
            wasm: module,
            maxStackSize: INLINE_MAX_STACK_SIZE,
            interruptBudget,
            shouldInterrupt: () => {
                if (stopped || settled || exhausted)
                    return true;
                if (++polls <= interruptBudget)
                    return false;
                exhausted = true;
                return true;
            },
            post: (message) => {
                const terminal = message.type === "done" || message.type === "crash";
                // Only the first terminal message counts: a crash caused by interrupting a settled VM is noise.
                if (terminal && settled)
                    return;
                if (terminal)
                    settled = true;
                queueMicrotask(() => {
                    if (stopped)
                        return;
                    // The interrupt surfaces as a crash or a failed done; report what caused it instead.
                    if (exhausted && (message.type === "done" || message.type === "crash")) {
                        events.failure({
                            kind: "timeout",
                            message: `Execution exceeded its interrupt budget of ${interruptBudget}`,
                        });
                        return;
                    }
                    events.message(message);
                });
            },
        });
        return {
            post: (message) => {
                if (!stopped)
                    session.deliver(message);
            },
            stop: async () => {
                if (stopped)
                    return;
                stopped = true;
                session.dispose();
            },
        };
    };
}

export function isWorkerToHostMessage(value) {
    if (typeof value !== "object" || value === null)
