        let channel;
        let ended = false;
        let buffered = [];
        let bufferedChars = 0;
        /** Replies that arrived before the launcher returned the channel. */
        const unsent = [];
        const takeBuffer = () => {
            const batch = buffered;
            buffered = [];
            bufferedChars = 0;
            return batch;
        };
        const end = (terminal) => {
            if (ended)
                return;
            ended = true;
            const batch = takeBuffer();
            const delivered = terminal ? exchange([...batch, terminal]).catch(() => null) : Promise.resolve();
            void delivered
                .then(() => channel?.stop())
                .catch(() => undefined)
                .then(() => resolve());
