 * call whatever tools the agent loop provides at execution time.
 */
export function createCodemodeTool(tools = [], options = {}) {
    const definition = createCodemodeToolDefinition(options);
    const tool = wrapToolDefinition(definition);
    Object.assign(tool, {
        description: createCodemodeDescription(tools, { models: options.models === true }),
        promptSnippet: definition.promptSnippet,
        promptGuidelines: definition.promptGuidelines,
    });

function formatCallSummary(calls) {
    if (calls.length === 0)
        return "No tool calls were made.";
    return `Tool calls made before the failure (they are not undone): ${calls.map((call) => `${call.name} (${call.status})`).join(", ")}`;
}
function formatError(result, calls) {
    const { error } = result;
    const head = error.kind === "script"
        ? (error.stack ?? `${error.name ?? "Error"}: ${error.message}`)
        : error.kind === "timeout"
            ? `Script timed out: ${error.message}`
            : error.kind === "aborted"
                ? `Script aborted: ${error.message}`
                : `Script sandbox failed: ${error.message}`;
    return `${head}\n\n${formatCallSummary(calls)}`;

export async function executeCodemode(toolCallId, input, signal, onUpdate, ctx, options = {}) {
    const startedAt = performance.now();
    const { code, options: sourceOptions } = parseCodemodeSource(input.code);
    const calls = [];
    // Usage of the script's `models.*` calls. Nested tool calls report theirs through the session.
    let modelUsage;
    // Images returned by `models.generateImages()`, to notice a script that never shows them.
    let generatedImages = 0;
    const addGeneratedImages = (count) => {
        generatedImages += count;
    };
    const addModelUsage = (usage) => {
        modelUsage = modelUsage ? combineUsage(modelUsage, usage) : usage;
    };
    const snapshot = () => ({ calls: calls.map((call) => ({ ...call })) });
    const publish = () => onUpdate?.({ content: [], details: snapshot() });
    // Show the script as running before its first nested call, so the row's timer starts.
    publish();
    const callable = ctx ? getCodemodeCallableTools(ctx.tools) : [];
    // ALL_TOOLS entries carry the declaration.
    const guidelines = options.getToolGuidelines?.();
    const samples = new Map(callable.map((tool) => [tool.name, renderToolSample(toCodemodeDeclaration(tool, guidelines?.get(tool.name)))]));
    const sandboxTools = callable.map((tool) => ({
        name: tool.name,
        description: samples.get(tool.name),
        execute: async (args, { signal: callSignal }) => {

// The wait for a worker counts toward the script's deadline.
const deadline = sourceOptions.timeoutMs ?? Number.POSITIVE_INFINITY;
const waitStartedAt = performance.now();
const admission = await reserveCodemodeWorker(signal, Math.min(deadline, CODEMODE_WORKER_WAIT_MS));
const waitedMs = performance.now() - waitStartedAt;
if (admission !== "reserved") {
    const waited = ((performance.now() - startedAt) / 1000).toFixed(1);
    const reason = signal?.reason;
    const error = admission === "aborted"
        ? `Script aborted: ${reason instanceof Error ? reason.message : "Execution aborted"}`
        : deadline <= CODEMODE_WORKER_WAIT_MS
            ? `Script timed out: Execution timed out after ${deadline} ms while waiting for a free codemode worker`
            : `No codemode worker became free within ${CODEMODE_WORKER_WAIT_MS / 1000} seconds. All ${maxCodemodeWorkers()} workers, shared by every session in this process, are held by other scripts. Retry after they finish.`;
    return {
        content: [
            { type: "text", text: `Script failed\nWall time ${waited} seconds\nOutput:\n` },
            { type: "text", text: `Script error:\n${error}\n\nThe script did not start.` },
        ],
        details: snapshot(),
        isError: true,
    };
}
// The reservation covers the one worker this script starts. A launch that resumes after the result
// settled finds it released and starts no worker.
let reserved = true;
let sandbox;
let result;
try {
    sandbox = new CodemodeSandbox({
        tools: sandboxTools,
        globals: [
            ...createDiscoveryGlobals(callable, samples, options),
            ...(options.models && ctx
                ? createModelGlobals(ctx.modelRegistry, toolCallId, calls, publish, addModelUsage, addGeneratedImages)
                : []),
        ],
        timeoutMs: Math.max(1, Math.round(deadline - waitedMs)),
        memoryLimitBytes: CODEMODE_MEMORY_LIMIT_BYTES,
        wasm: loadQuickJSWasm(getQuickJSWasmPath()),
        workerUrl: getCodemodeWorkerSpecifier(),
        acquireWorker: () => {
            if (!reserved)
                throw new Error("The script already settled");
            // From here the sandbox releases the slot when the worker actually exits.
            reserved = false;
            return releaseCodemodeWorker;
        },
    });
    const store = ctx ? readCodemodeStore(ctx.sessionManager.getBranch()) : {};
    result = await sandbox.execute(code, { signal, store });
}
finally {
    await sandbox?.close();
    if (reserved) {
        reserved = false;
        releaseCodemodeWorker();
    }
}

const scriptOutput = [...result.output];
if (result.ok) {
    const { set, delete: deleted } = result.storeWrites;
    if (Object.keys(set).length > 0 || deleted.length > 0) {
        options.appendEntry?.(CODEMODE_STORE_ENTRY_TYPE, { set, delete: deleted });
    }
    // pi extension: a returned value is appended like text().
    if (result.value !== undefined)
        scriptOutput.push({ type: "text", text: valueText(result.value) });
}
const items = formatOutput(scriptOutput);
if (!result.ok)
    items.push({ type: "text", text: `Script error:\n${formatError(result, calls)}` });
if (generatedImages > 0 && !items.some((item) => item.type === "image")) {
    items.push({
        type: "text",
        text: `Note: models.generateImages() returned ${generatedImages} image${generatedImages === 1 ? "" : "s"} that the script did not show. Show each image block of result.output with image(block).`,
    });
}
const truncated = await truncateOutput(joinAdjacentText(items), sourceOptions.maxOutputTokens ?? DEFAULT_MAX_OUTPUT_TOKENS);
// After truncation, which joins the text items and moves images after them, so each path stays
// next to its image and is never cut.
const output = joinAdjacentText(await saveImages(truncated.items));
const wallTime = ((performance.now() - startedAt) / 1000).toFixed(1);
const header = `${result.ok ? "Script completed" : "Script failed"}\nWall time ${wallTime} seconds\nOutput:\n`;
const details = snapshot();
if (truncated.fullOutputPath)
    details.fullOutputPath = truncated.fullOutputPath;
return {
    content: [{ type: "text", text: header }, ...output],
    details,
    ...(modelUsage ? { usage: modelUsage } : {}),
    ...(result.ok ? {} : { isError: true }),
};

renderResult(result, options, theme, context) {
    const timerText = toolTimerText(context, options.isPartial);
    const component = context.lastComponent ?? new Container();
    component.clear();
    const calls = result.details?.calls ?? [];
    if (calls.length > 0) {
        const shown = options.expanded ? calls : calls.slice(-CALL_PREVIEW_COUNT);
        const lines = shown.map((call) => formatCall(call, theme, options.expanded));
        if (shown.length < calls.length) {
            lines.unshift(`${theme.fg("muted", `... (${calls.length - shown.length} earlier calls,`)} ${keyHint("app.tools.expand", "to expand")}${theme.fg("muted", ")")}`);
        }
        // Collapsed rows hide earlier calls, so the total covers every call.
        const priced = calls.filter((call) => call.cost);
        if (priced.length > 1) {
            const total = priced.reduce((sum, call) => sum + (call.cost ?? 0), 0);
            lines.push(theme.fg("muted", `Model calls: ${formatCost(total)}`));
        }
        component.addChild(new Spacer(1));
        component.addChild(new Text(lines.join("\n"), 0, 0));
    }
    // Drop the "Script completed\nWall time ...\nOutput:\n" header. Rejected input (invalid options)
    // has no header.
    const [first, ...rest] = result.content;
    const hasHeader = first?.type === "text" && SCRIPT_HEADER.test(first.text);
    const output = options.isPartial
        ? ""
        : getTextOutput({ ...result, content: hasHeader ? rest : result.content }, context.showImages).trim();
    if (output) {
        const color = context.isError ? "error" : "toolOutput";
        const styled = replaceTabs(output)
            .split("\n")
            .map((line) => theme.fg(color, line))
            .join("\n");
        component.addChild(new Spacer(1));
        if (options.expanded) {
            component.addChild(new Text(styled, 0, 0));
        }
        else {
            // Limit wrapped lines, not logical ones: script output is often one long JSON line.
            component.addChild(new VisualLinePreview({
                text: styled,
                maxVisualLines: OUTPUT_PREVIEW_LINES,
                keep: "start",
                formatHint: (hidden) => expandHint(theme, hidden, "lines"),
            }));
            // The collapsed preview hides the truncation notice at the end, so name the file here.
            const fullOutputPath = result.details?.fullOutputPath;
            if (fullOutputPath)
                component.addChild(new Text(theme.fg("muted", `Full output: ${fullOutputPath}`), 0, 0));
        }
    }
    if (timerText) {
        component.addChild(new Spacer(1));
        component.addChild(new Text(theme.fg("muted", timerText), 0, 0));
    }
    return component;

_handleAgentEvent = async (event) => {
    if (event.type === "tool_execution_update" && this.resourceLoader.contentPolicy) {
        try {
            if (this.resourceLoader.contentPolicy.shouldInspectTool(event.toolName, event.args)) return;
        } catch { return; }
    }
    if (event.type === "tool_execution_end" && this.resourceLoader.contentPolicy) {
        event = { ...event, result: { content: event.result.content, details: event.result.details, structuredContent: event.result.structuredContent, usage: event.result.usage, terminate: event.result.terminate } };

    const inspect =
        !this.agent.signal?.aborted &&
        (event.message.role !== "toolResult" || policy.shouldInspectTool?.(event.message.toolName, undefined));
    if (inspect) {
        try {
            const admitted = await policy.filterContext([event.message], this.agent.signal);
            if (!Array.isArray(admitted) || admitted.length !== 1 || admitted[0].role !== event.message.role) throw new Error("Invalid content-policy result");
            this._replaceMessageInPlace(event.message, admitted[0]);
        } catch {
            if (event.message.role === "toolResult") {
                this._replaceMessageInPlace(event.message, {
                    role: "toolResult", toolCallId: event.message.toolCallId, toolName: event.message.toolName, timestamp: event.message.timestamp,
                    content: [{ type: "text", text: "TextGuard could not check this message; content withheld." }], details: {}, isError: true,
                });
            } else if (event.message.role === "user") {
                this._replaceMessageInPlace(event.message, {
                    role: "user", timestamp: event.message.timestamp,
                    content: [{ type: "text", text: "TextGuard could not check this message; content withheld." }],
                });
            }
            // Assistant, custom, and bashExecution messages are not scanned here; on a failed
            // check they must stay intact so required provider metadata, session statistics,
            // and subscribers keep working instead of receiving an unusable placeholder shape.
        }
    }
}
// Emit to extensions first, then notify public listeners.
await this._emitExtensionEvent(event);
this._emit(event.type === "agent_end" ? { ...event, willRetry: this._willRetryAfterAgentEnd(event) } : event);
// Handle session persistence
if (event.type === "message_end") {
    let entryId;
    // Check if this is a custom message from extensions
    if (event.message.role === "custom") {
        // Persist as CustomMessageEntry
        entryId = this.sessionManager.appendCustomMessageEntry(event.message.customType, event.message.content, event.message.display, event.message.details);
        const entry = this.sessionManager.getEntry(entryId);
        if (entry)
            retainCustomContextMessage(entry, event.message);
    }
    else if (event.message.role === "system" ||
        event.message.role === "user" ||
        event.message.role === "assistant" ||
        event.message.role === "toolResult") {
        // Regular LLM message - persist as SessionMessageEntry
        entryId = this.sessionManager.appendMessage(event.message);

const updateEvents = [];
let acceptingUpdates = true;
const startedAt = performance.now();
const elapsed = () => Math.round(performance.now() - startedAt);
try {
    const result = await prepared.tool.execute(prepared.toolCall.id, prepared.args, signal, (partialResult) => {
        if (!acceptingUpdates)
            return;
        updateEvents.push(Promise.resolve(onUpdate(partialResult)));
    });
    const durationMs = elapsed();
    acceptingUpdates = false;
    await Promise.all(updateEvents);
    return { result, isError: result.isError === true, durationMs };
}
catch (error) {
    const durationMs = elapsed();
    acceptingUpdates = false;
    await Promise.all(updateEvents);
    return {
        result: createErrorToolResult(error instanceof Error ? error.message : String(error)),
        isError: true,
        durationMs,
    };
}
finally {
    acceptingUpdates = false;
}

async function emitToolExecutionEnd(finalized, emit) {
    await emit({
        type: "tool_execution_end",
        toolCallId: finalized.toolCall.id,
        toolName: finalized.toolCall.name,
        result: finalized.result,
        isError: finalized.isError,
        ...(finalized.durationMs === undefined ? {} : { durationMs: finalized.durationMs }),
    });
}
function createToolResultMessage(finalized) {
    return {
        role: "toolResult",
        toolCallId: finalized.toolCall.id,
        toolName: finalized.toolCall.name,
        // Untyped tools (JS extensions) can return results without content; normalize
        // so the null never enters session history or provider payloads.
        content: finalized.result.content ?? [],
        details: finalized.result.details,
        usage: finalized.result.usage,
        isError: finalized.isError,
        ...(finalized.durationMs === undefined ? {} : { durationMs: finalized.durationMs }),
        timestamp: Date.now(),
    };
}
async function emitToolResultMessage(toolResultMessage, emit) {
    await emit({ type: "message_start", message: toolResultMessage });
    await emit({ type: "message_end", message: toolResultMessage });

